int y;
int dx;
int tileX;
int count;
int tileY;
int dy;
int x;

for (dx = -1; dx < 3; dx++) {
    for (dy = -1, x = tileX + dx; dy < 3; dy++) {
        y = tileY + dy;
        if (x >= 0 && x <= 0x7f && y >= 0 && y <= 0x3f &&
            LifeA[x * 64 + y] != 0)
            count++;
    }
}
