}
for (dx = -1; dx < 3; dx++) {
    dy = -1;
    x = tileX + dx;
    do {
        y = tileY + dy;
        if (x >= 0 && x <= 0x7f && y >= 0 && y <= 0x3f &&
            LifeA[x * 64 + y] != 0)
            count++;
    } while (++dy < 3);
}

